CREATE SCHEMA IF NOT EXISTS stp;
CREATE TABLE IF NOT EXISTS stp.workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),public boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stp.members(workspace_id uuid REFERENCES stp.workspaces,id text NOT NULL,role text NOT NULL CHECK(role IN ('owner','reviewer','officer')),PRIMARY KEY(workspace_id,id));
CREATE TABLE IF NOT EXISTS stp.reports(workspace_id uuid REFERENCES stp.workspaces,id text NOT NULL,provider_id text NOT NULL,label text NOT NULL,zone text NOT NULL,officer_id text NOT NULL,round_date date NOT NULL,due_date date NOT NULL,PRIMARY KEY(workspace_id,id));
CREATE TABLE IF NOT EXISTS stp.submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,report_id text NOT NULL,version integer NOT NULL CHECK(version>0),scores jsonb NOT NULL,decision text NOT NULL DEFAULT 'draft' CHECK(decision IN ('draft','approved','rejected')),submitted_at timestamptz NOT NULL DEFAULT now(),actor text NOT NULL,reviewer text,review_note text,reviewed_at timestamptz,FOREIGN KEY(workspace_id,report_id) REFERENCES stp.reports(workspace_id,id),UNIQUE(workspace_id,report_id,version));
CREATE TABLE IF NOT EXISTS stp.actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES stp.workspaces,provider_id text NOT NULL,title text NOT NULL,owner text NOT NULL,due_date date NOT NULL,status text NOT NULL CHECK(status IN ('open','in_progress','closed')),evidence text NOT NULL DEFAULT '',verification text NOT NULL DEFAULT 'pending' CHECK(verification IN ('pending','verified')),revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),CHECK(status <> 'closed' OR (length(trim(evidence))>0 AND verification='verified')));
CREATE TABLE IF NOT EXISTS stp.audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES stp.workspaces,actor text NOT NULL,event text NOT NULL,record_id text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stp.access_codes(hash text PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES stp.workspaces,role text NOT NULL CHECK(role IN ('reviewer','officer')),expires_at timestamptz NOT NULL,redeemed_by text);
CREATE INDEX IF NOT EXISTS submission_workspace ON stp.submissions(workspace_id,report_id,version DESC);
CREATE INDEX IF NOT EXISTS audit_workspace ON stp.audit(workspace_id,id DESC);
